SELECT c.Id, c.Name
FROM Customers c
WHERE NOT EXISTS (SELECT 1 FROM Orders o WHERE o.CustomerId = c.Id);

WITH r AS (
  SELECT *, ROW_NUMBER() OVER (PARTITION BY CustomerId
                               ORDER BY CreatedAt DESC, Id DESC) AS rn
  FROM Orders
)
SELECT * FROM r WHERE rn <= 3;

ALTER TABLE Orders ADD
  CONSTRAINT FK_Orders_Customers FOREIGN KEY (CustomerId) REFERENCES Customers(Id),
  CONSTRAINT CK_Orders_Total CHECK (Total >= 0);
CREATE INDEX IX_Orders_CustomerId ON Orders (CustomerId);

SET STATISTICS IO, TIME ON;
EXEC dbo.GetOrders @CustomerId = 42;
-- Query Store: regresje planów
SELECT TOP (20) q.query_id, p.plan_id, rs.avg_duration
FROM sys.query_store_runtime_stats rs
JOIN sys.query_store_plan p ON p.plan_id = rs.plan_id
JOIN sys.query_store_query q ON q.query_id = p.query_id
ORDER BY rs.avg_duration DESC;

SET XACT_ABORT ON;
BEGIN TRY
  BEGIN TRAN;
    UPDATE Accounts SET Balance -= @amt WHERE Id = @from AND Balance >= @amt;
    IF @@ROWCOUNT = 0 THROW 50001, 'Insufficient funds', 1;
    UPDATE Accounts SET Balance += @amt WHERE Id = @to;
  COMMIT;
END TRY
BEGIN CATCH
  IF @@TRANCOUNT > 0 ROLLBACK;
  THROW;
END CATCH;

WHILE 1 = 1
BEGIN
  DELETE TOP (4000) FROM dbo.Logs WHERE CreatedAt < @cutoff;
  IF @@ROWCOUNT = 0 BREAK;
END;

ALTER TABLE Products ADD Color AS JSON_VALUE(Attributes, '$.color');
CREATE INDEX IX_Products_Color ON Products (Color);

